async def watch(queue: asyncio.Queue[str], budget: float = 60.0) -> None:
    while True:
        try:
            msg = await asyncio.wait_for(queue.get(), timeout=budget)   # 3.11+: async with asyncio.timeout(budget)
        except asyncio.TimeoutError:               # the same class as builtin TimeoutError from 3.11 on
            await alert(f"no messages for {budget}s")                   # absence == exception
        else:
            await handle(msg)                                          # arrival restarts the budget

